export function formatPace(distanceKm: number, timeSec: number): string {
  if (distanceKm <= 0) throw new Error('Дистанція має бути більшою за 0');
  const secPerKm = Math.round(timeSec / distanceKm);
  const min = Math.floor(secPerKm / 60);
  const sec = secPerKm % 60;
  return `${min}:${sec < 10 ? '0' : ''}${sec} /км`;
}

