export function aggregateWorkouts(workouts: Workout[]): WorkoutSummary {
  // Якщо масив порожній — падає через ділення на workouts.length без перевірки (NaN)
  const avg = workouts.reduce((s, w) => s + w.duration, 0) / workouts.length;
  return { total: workouts.length, avgDuration: avg };
}

